import uuid

import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.EmoteList{PlayerRuntimeID: 300, EmotePieces: []uuid.UUID{
# uuid.MustParse("01020304-0506-0708-090a-0b0c0d0e0f10"), uuid.MustParse("00000000-0000-0000-0000-000000000002")}}
TWO_PIECES = bytes.fromhex("ac02020807060504030201100f0e0d0c0b0a0900000000000000000200000000000000")

# generated by gophertunnel b8bd735:
# &packet.EmoteList{PlayerRuntimeID: 7}
NO_PIECES = bytes.fromhex("0700")

GOLDENS = [
    pytest.param(
        v2225.EmoteListPacket(
            runtime_id=300,
            emote_piece_ids=[
                uuid.UUID("01020304-0506-0708-090a-0b0c0d0e0f10"),
                uuid.UUID("00000000-0000-0000-0000-000000000002"),
            ],
        ),
        TWO_PIECES,
        id="two-pieces",
    ),
    pytest.param(v2225.EmoteListPacket(runtime_id=7), NO_PIECES, id="no-pieces-is-a-zero-count"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_emote_list_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_emote_list_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_emote_list_rejects_a_piece_id_one_byte_short():
    with pytest.raises(ValueError, match="at byte"):
        v2225.EmoteListPacket.from_bytes(TWO_PIECES[:-1])
